import fs from 'node:fs';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { CAMPUS_JSON, NAV_JSON, SCATTER_JSON } from '../src/lib/assets';
import { loadCampus, loadNav, loadScatter } from '../src/lib/data';

// 7-16: prove the loaders request the hashed URLs generated by `make assets`,
// and that their zod/schema validation still accepts the committed files.
afterEach(() => vi.unstubAllGlobals());

describe('public data loaders (7-15)', () => {
  it('fetches campus, nav and scatter through content-hashed URLs', async () => {
    const calls: string[] = [];
    vi.stubGlobal('fetch', vi.fn(async (url: string) => {
      calls.push(url);
      const file = `public${url.slice(0, url.indexOf('?') === -1 ? undefined : url.indexOf('?'))}`;
      return {
        ok: true,
        status: 200,
        json: async () => JSON.parse(fs.readFileSync(file, 'utf8')),
      };
    }));

    const campus = await loadCampus();
    const nav = await loadNav();
    const scatter = await loadScatter();

    expect(calls).toEqual([CAMPUS_JSON, NAV_JSON, SCATTER_JSON]);
    expect(calls.every((url) => /\?v=[0-9a-f]{10}$/.test(url))).toBe(true);
    expect(campus.buildings.length).toBe(54);
    expect(nav.nodes.length).toBe(626);
    expect(nav.links.length).toBe(666);
    expect(scatter.length).toBe(330);
  });
});
